    /** Retourne le poids formaté lisiblement */
    public static function formatWeight(?int $grams): string
    {
        if (!$grams) return 'Microscopique';
        if ($grams < 1000) return $grams . ' g';
        return number_format($grams / 1000, 2, ',', '') . ' kg';
    }
